{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The launch template does not specify the metadata options, potentially allowing IMDSv1, which is less secure than IMDSv2."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"changeme_simple_asg_launch_template_nlb\" {\n  name                   = \"changeme-simple-asg-launch-template-nlb\"\n  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id\n  instance_type          = \"t2.micro\"\n  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]\n  user_data              = filebase64(\"${path.module}/user_data.sh\")\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Added metadata_options block to the aws_launch_template resource to require IMDSv2 by setting http_tokens to 'required'."
}
